S = "Hakeem Force Academy"
QS = [
(S, "What was the name of the father of Hazrat Yunus (AS)?", ["Matta", "Imran", "Amoz", "Azar"], 0, "According to Islamic tradition, Hazrat Yunus (AS) was the son of Matta (Matthew). He was sent to the people of Nineveh.", "Hazrat Yunus (AS) is also called Dhun-Nun and Sahib al-Hut because of the incident of the fish.", [3923]),
(S, "Who was the father of Hazrat Yaqub (AS)?", ["Hazrat Ishaq (AS)", "Hazrat Ibrahim (AS)", "Hazrat Ismail (AS)", "Hazrat Yusuf (AS)"], 0, "Hazrat Yaqub (AS) was the son of Hazrat Ishaq (AS) and the grandson of Hazrat Ibrahim (AS).", "Hazrat Yaqub (AS) was the father of Hazrat Yusuf (AS).", [4929]),
(S, "Hazrat Fatima (RA) was the wife of whom?", ["Hazrat Uthman (RA)", "Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)"], 1, "Hazrat Fatima (RA) married Hazrat Ali (RA) in 2 AH.", "Their children were Hazrat Hasan, Hazrat Husain, Hazrat Zainab and Hazrat Umm Kulthum (RA).", [676]),
(S, "What was the relation of Hazrat Fatima (RA) to Hazrat Muhammad (PBUH)?", ["Wife", "Sister", "Daughter", "Aunt"], 2, "Hazrat Fatima (RA) was the youngest daughter of the Holy Prophet (PBUH) and Hazrat Khadija (RA).", "She is known as Zahra and Sayyidat Nisa al-Alamin.", [3943]),
(S, "In which year was Fatima Jinnah born?", ["1893", "1901", "1885", "1876"], 0, "Fatima Jinnah, the sister of Quaid-e-Azam, was born in Karachi in 1893.", "Her birth date is given as 30 or 31 July 1893 in different sources, and she died in 1967.", [3321]),
(S, "In which city was Fatima Jinnah born?", ["Lahore", "Bombay", "Karachi", "Delhi"], 2, "Fatima Jinnah was born in Karachi in 1893 into the family of Jinnahbhai Poonja.", "She was given the title Madar-e-Millat (Mother of the Nation).", [4226]),
(S, "Surah Al-Fil of the Holy Quran is named after which animal?", ["Camel", "Elephant", "Horse", "Cow"], 1, "Al-Fil means the elephant. The surah describes how Allah destroyed the army of Abraha that came with elephants to demolish the Kaaba.", "The Holy Prophet (PBUH) was born in the same Year of the Elephant.", [2698]),
(S, "In a class of 33 students, 2/3 are boys. How many are girls?", ["22", "10", "11", "13"], 2, "Boys = 2/3 of 33 = 22. Girls = 33 - 22 = 11.", "Girls are 1/3 of the class, which is the same as 33 divided by 3.", [2116]),
(S, "Which female is mentioned by name in the Holy Quran?", ["Hazrat Khadija (RA)", "Hazrat Aisha (RA)", "Hazrat Fatima (RA)", "Hazrat Maryam (AS)"], 3, "Hazrat Maryam (AS), the mother of Hazrat Isa (AS), is the only woman mentioned by name in the Quran.", "Surah Maryam, the 19th surah, is named after her.", [1136]),
(S, "Who won the FIFA World Cup 2018, held in Russia?", ["Croatia", "Belgium", "Germany", "France"], 3, "France beat Croatia 4-2 in the final on 15 July 2018 in Moscow.", "France won its second title in 2018, and Argentina won the next one in 2022 in Qatar.", [92]),
(S, "Which country won the first FIFA World Cup in 1930?", ["Uruguay", "Argentina", "Brazil", "Italy"], 0, "Uruguay hosted the first FIFA World Cup in 1930 and beat Argentina 4-2 in the final.", "Pakistan won the first Hockey World Cup in 1971.", [357]),
(S, "To which country did the World War 2 leader Winston Churchill belong?", ["United States", "United Kingdom", "Soviet Union", "France"], 1, "Winston Churchill was the Prime Minister of the United Kingdom during most of World War 2 (1940-1945).", "He also served a second term as Prime Minister from 1951 to 1955.", [2786]),
(S, "Find X: 3 : X :: 4 : 12", ["9", "12", "6", "8"], 0, "The ratio 4:12 equals 1:3, so 3:X must also be 1:3. Therefore X = 3 x 3 = 9.", "In a proportion a:b :: c:d, the product of extremes equals the product of means (ad = bc).", [1672]),
(S, "If the ordered pairs (x, y - 1) and (2, -1) are equal, what are the values of x and y?", ["x = 2, y = 2", "x = -1, y = 2", "x = 2, y = 0", "x = 0, y = 2"], 2, "Equal ordered pairs have equal coordinates. So x = 2 and y - 1 = -1, which gives y = 0.", "Ordered pairs (a, b) and (c, d) are equal only when a = c and b = d.", [1725]),
(S, "What is the height of K2 in feet?", ["29,032 feet", "26,660 feet", "27,940 feet", "28,251 feet"], 3, "K2 is 8,611 metres high. Multiplying by 3.28 gives about 28,251 feet.", "K2 is the second highest mountain in the world after Mount Everest at 29,032 feet.", [3405]),
(S, "Choose the correct word to fill the blank: ______ M.A degree is required for this job.", ["An", "A", "The", "In"], 0, "M is pronounced 'em', which begins with a vowel sound, so the article 'an' is used.", "The choice of a or an depends on the sound, not on the spelling, of the following word.", [554]),
(S, "Which of the following is a prime number: 7, 9, 18, 21?", ["9", "7", "18", "21"], 1, "7 has only two factors, 1 and 7. 9 = 3 x 3, 18 = 2 x 9 and 21 = 3 x 7 are composite.", "2 is the only even prime number.", [543]),
(S, "The Flemish people are found mainly in which country?", ["Netherlands", "Switzerland", "Belgium", "Germany"], 2, "The Flemish are the Dutch-speaking people of Flanders, the northern region of Belgium.", "The French-speaking people of southern Belgium are called Walloons.", [409, 2989, 4176]),
(S, "Electric current is due to the flow of what?", ["Protons", "Neutrons", "Atoms", "Electrons"], 3, "In a metallic conductor, the free electrons drift under a potential difference, and this flow of charge is the electric current.", "The SI unit of electric current is the ampere.", [251]),
(S, "Into which sea does the Indus River flow?", ["Arabian Sea", "Bay of Bengal", "Red Sea", "Caspian Sea"], 0, "The Indus River flows through Pakistan and falls into the Arabian Sea near Karachi in Sindh.", "The Indus delta lies south-east of Thatta.", [2299]),
(S, "Who made the first solo non-stop flight across the Atlantic Ocean in 1927?", ["Amelia Earhart", "Wilbur Wright", "Charles Lindbergh", "Neil Armstrong"], 2, "Charles Lindbergh flew the Spirit of St. Louis alone from New York to Paris in May 1927.", "Amelia Earhart became the first woman to fly solo across the Atlantic in 1932.", [4989]),
(S, "Who made the first successful powered aeroplane flight in 1903?", ["Wright brothers", "Montgolfier brothers", "Alexander Graham Bell", "Charles Lindbergh"], 0, "Orville and Wilbur Wright flew the first powered, controlled aeroplane at Kitty Hawk, USA, on 17 December 1903.", "The Montgolfier brothers made the first hot air balloon flight in 1783.", [5128, 4835]),
(S, "What is the synonym of the word 'foment'?", ["Calm", "Incite", "Prevent", "Cure"], 1, "To foment means to stir up or encourage trouble or unrest, which is the same as to incite.", "Foment can also mean to treat a body part with warmth or lotion.", [310, 3266]),
(S, "Change into passive voice: It is time to eat food.", ["It is time that food eats.", "Food is time to be eaten.", "It is time for food to be eaten.", "It was time for food to be eaten."], 2, "The active infinitive 'to eat food' becomes 'for food to be eaten' in the passive, with the present tense 'is' kept.", "In passive voice the object of the active sentence becomes the subject.", [1589]),
(S, "Change into active voice: By whom is the boy being fed?", ["Who is feeding the boy?", "Who was feeding the boy?", "Who has fed the boy?", "Whom is the boy feeding?"], 0, "The passive 'is being fed' (present continuous) becomes 'is feeding' in the active, and 'by whom' becomes 'who'.", "The agent after 'by' becomes the subject of the active sentence.", [1576]),
(S, "Shoe is to foot as helmet is to what?", ["Hand", "Head", "Neck", "Knee"], 1, "A shoe is worn to protect the foot, and a helmet is worn to protect the head.", "This is a type of analogy based on an object and the body part it protects.", [2678]),
(S, "Which one is different from the rest: square, yard, meter, foot?", ["Yard", "Foot", "Meter", "Square"], 3, "Yard, meter and foot are units of length. Square is a geometric shape.", "One yard equals three feet, and one meter is about 3.28 feet.", [4401]),
]
